    81→
    82→public(package) fun deposit_ctoken<MarketType, CoinType>(
    83→    self: &mut Obligation<MarketType>,
    84→    ctoken: Balance<CToken<MarketType, CoinType>>,
    85→) {
    86→    assert!(
    87→        !self.debts.contains(type_name::with_defining_ids<CoinType>()),
    88→        error::obligation_deposit_borrowed_asset(),
    89→    );
    90→    if (!self.ctokens.is_supporting_collateral<MarketType, CoinType>()) {
    91→        self.ctokens.support_collateral_token<MarketType, CoinType>();
    92→    };
    93→    self.ctokens.join_ctoken(ctoken);
    94→}
    95→
    96→public(package) fun withdraw_ctokens<MarketType, CoinType>(
    97→    self: &mut Obligation<MarketType>,
    98→    amount: u64,
    99→): Balance<CToken<MarketType, CoinType>> {
   100→    assert!(
   101→        self.ctokens.is_supporting_collateral<MarketType, CoinType>(),
   102→        error::obligation_withdraw_no_deposit(),
   103→    );
   104→    self.ctokens.split_ctoken<MarketType, CoinType>(amount)
   105→}
   106→
   107→/// Try borrow the asset, increase the debt. Returns the latest asset debt.
   108→public(package) fun try_borrow_asset<MarketType, CoinType>(
   109→    self: &mut Obligation<MarketType>,
   110→    amount: u64,
   111→    asset_borrow_index: Decimal,
   112→): Decimal {
   113→    let name = type_name::with_defining_ids<CoinType>();
   114→
   115→    let amount = math::float::from(amount);
   116→
   117→    if (!self.debts.contains(type_name::with_defining_ids<CoinType>())) {
   118→        // no borrow before, init borrow
   119→
   120→        // do not allow borrowing of collateral asset, mess up book keeping
   121→        assert!(
   122→            !self.ctokens.is_supporting_collateral<MarketType, CoinType>(),
   123→            error::obligation_borrow_collateral_asset(),
   124→        );
   125→
   126→        wit_table::add(
   127→            ObligationDebts {},
   128→            &mut self.debts,
   129→            name,
   130→            debt::new(amount, asset_borrow_index),
   131→        );
   132→
   133→        return amount
   134→    };
   135→
   136→    let debt = self.accrue_interest(type_name::with_defining_ids<CoinType>(), asset_borrow_index);
   137→
   138→    // this is safe to do because it has accrued interest before
   139→    debt.unsafe_increase(amount);
   140→    debt.unsafe_debt_amount()
   141→}
   142→
   143→/// Obligation repays debt, returns 
   144→public(package) fun repay_debt<MarketType, CoinType>(
   145→    self: &mut Obligation<MarketType>,
   146→    amount: u64,
   147→    asset_borrow_index: Decimal,
   148→): u64 {
   149→    let _ = self.accrue_interest(type_name::with_defining_ids<CoinType>(), asset_borrow_index);
   150→    self.unsafe_repay_debt_only<MarketType, CoinType>(amount)
   151→}
   152→
   153→/// Checks the invariants after borrow or repay that must be met
   154→public(package) fun enforce_post_borrow_repay_invariant<MarketType, CoinType>(
   155→    self: &Obligation<MarketType>,
   156→    min_borrow_amount: u64
   157→) {
   158→    let coin_type = type_name::with_defining_ids<CoinType>();
   159→
   160→    if (!self.has_debt<MarketType>(coin_type)){
   161→        return
   162→    };
   163→
   164→    let current_debt = self.debt<MarketType>(coin_type).unsafe_debt_amount();
   165→    assert!(current_debt.ge_u64(min_borrow_amount), error::obligation_borrow_below_min());
   166→}
   167→
   168→/// Directly updating the debt repay, without checking if interest is up to date.
   169→/// The caller makes sure the obligation interest is already updated to date
   170→public(package) fun unsafe_repay_debt_only<MarketType, CoinType>(
   171→    self: &mut Obligation<MarketType>,
   172→    amount: u64,
   173→): u64 {
   174→    let name = type_name::with_defining_ids<CoinType>();
   175→    let debt = wit_table::borrow_mut(ObligationDebts {}, &mut self.debts, name);
   176→
   177→    let debt_amount = debt.unsafe_debt_amount().ceil();
   178→
   179→    let residual = if (debt_amount <= amount) {
   180→        debt.cleared();
   181→
   182→        // repay a bit more than actually owned, almost neglegible
   183→        amount - debt_amount
   184→    } else {
   185→        debt.unsafe_decrease(math::float::from(amount));
   186→        0
   187→    };
   188→
   189→    if (!debt.has_debt()) {
   190→        wit_table::remove(ObligationDebts {}, &mut self.debts, name);
   191→    };
   192→
   193→    residual
   194→}
